import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Runbook QA — M25: presenza in tempo reale (1.8.2)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m25-presenza.md","filePath":"qa/m25-presenza.md"}'),d={name:"qa/m25-presenza.md"};function s(n,e,i,c,l,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="runbook-qa-—-m25-presenza-in-tempo-reale-1-8-2" tabindex="-1">Runbook QA — M25: presenza in tempo reale (1.8.2) <a class="header-anchor" href="#runbook-qa-—-m25-presenza-in-tempo-reale-1-8-2" aria-label="Permalink to &quot;Runbook QA — M25: presenza in tempo reale (1.8.2)&quot;">​</a></h1><p>Prove manuali <strong>a carico dell&#39;owner</strong>: nessuna è stata eseguita con utenti reali durante lo sviluppo (i test automatici usano un server finto e due «repliche» sullo stesso PostgreSQL). Decisione: <a href="./../adr/0065-presenza-in-tempo-reale.html">ADR-0065</a>. Guide: <a href="./../user-guide/presenza.html">utente</a>, <a href="./../admin-guide/presenza.html">amministratore</a>.</p><h2 id="preparazione" tabindex="-1">Preparazione <a class="header-anchor" href="#preparazione" aria-label="Permalink to &quot;Preparazione&quot;">​</a></h2><ul><li>Stack con <code>task stack-up</code> e <code>task dev-cloud</code> (oppure un cloud vero). Utenti di sviluppo <code>user1</code> e <code>user2</code> (password <code>clarae-dev-password</code>); <code>scripts/run-desktop-with-cloud.sh --two-devices</code> avvia due client.</li><li>Un <strong>vault condiviso</strong> di <code>user1</code>, condiviso con <code>user2</code> come Editor, con alcune note sincronizzate, un disegno (<code>.excalidraw</code>) e un canvas (<code>.canvas</code>). <code>user1</code> usa il desktop, <code>user2</code> il workbench web nel browser (o viceversa, poi invertire).</li><li>Flag <code>features.presence</code> acceso (default). Annotare per ogni caso: esito, sistema operativo, browser, nota.</li></ul><h2 id="casi" tabindex="-1">Casi <a class="header-anchor" href="#casi" aria-label="Permalink to &quot;Casi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Prova</th><th>Atteso</th></tr></thead><tbody><tr><td>P1</td><td><code>user1</code> (desktop) e <code>user2</code> (web) aprono la stessa nota in primo piano</td><td>Ognuno vede <strong>l&#39;avatar dell&#39;altro</strong> nella barra dell&#39;Esplora file, con iniziali, colore e nome nel tooltip; nessuno vede il proprio</td></tr><tr><td>P2</td><td><code>user1</code> muove il mouse sul testo della nota</td><td><code>user2</code> vede il puntatore con l&#39;etichetta del nome di <code>user1</code>, che segue la riga e la colonna; scrivere senza muovere il mouse non lo sposta</td></tr><tr><td>P3</td><td><code>user2</code> chiude la nota, o cambia scheda in primo piano</td><td>L&#39;avatar e il cursore di <code>user2</code> spariscono da <code>user1</code> (pulizia dei cursori), nessun puntatore resta fermo</td></tr><tr><td>P4</td><td>Stesso account su due dispositivi, stessa nota</td><td>Nessun avatar per sé stessi (solo gli altri utenti)</td></tr><tr><td>P5</td><td>Vault <strong>privato</strong></td><td>Nessun avatar, nessuna connessione di presenza; nessun errore visibile</td></tr><tr><td>P6</td><td><strong>Share di cartella</strong> <code>Progetti/</code> a <code>user2</code> (mount): entrambi aprono un file della cartella; poi <code>user1</code> apre un file fuori dalla cartella</td><td>Presenza sul file della cartella (anche se il percorso nel mount è diverso); nessuna presenza sul file fuori dallo scope di <code>user2</code></td></tr><tr><td>P7</td><td>Nota <strong>appena creata e non ancora sincronizzata</strong></td><td>Nessun avatar finché non è sincronizzata; dopo la sincronizzazione e la riapertura la presenza funziona</td></tr><tr><td>P8</td><td><strong>Revoca</strong> della condivisione a <code>user2</code> mentre i due sono nella stessa nota</td><td>Entro pochi secondi (al più 60 s) <code>user1</code> non vede più <code>user2</code>; <code>user2</code> non riceve più i cursori; la connessione non resta aperta sul file</td></tr><tr><td>P9</td><td><strong>Sospensione</strong> di <code>user2</code> (console admin) durante la sessione</td><td>La connessione di <code>user2</code> si chiude subito; <code>user1</code> non lo vede più; <code>user2</code> non riesce a rientrare finché è sospeso</td></tr><tr><td>P10</td><td><strong>Flag spento a caldo:</strong> nel Config Profile di <code>user2</code> impostare <code>features.presence</code> a <code>false</code> con le sessioni aperte</td><td>Avatar e cursori spariscono da entrambi (al più 60 s); il client non riapre la connessione; riacceso, la presenza riparte</td></tr><tr><td>P11</td><td><strong>Più repliche</strong> (Helm con <code>api.replicas</code> ≥ 2, <code>user1</code> e <code>user2</code> su repliche diverse: verificarlo dai log in <code>debug</code> o forzando con due pod)</td><td>La presenza funziona tra repliche; fermando la replica di <code>user2</code> il suo avatar sparisce da <code>user1</code> <strong>entro 70 s</strong>; il cursore resta fluido</td></tr><tr><td>P12</td><td><strong>Proxy con timeout:</strong> lasciare le due sessioni ferme (senza muovere il mouse) per più di 2 minuti dietro l&#39;Ingress del chart</td><td>Nessuna disconnessione né ricollegamento (<code>ingress.presence.timeoutSeconds</code> 3600). Provarlo anche con il valore a 30 per vedere il difetto</td></tr><tr><td>P13</td><td><strong>Safari ≥ 15.4</strong> (e Safari &lt; 15.4, se disponibile): workbench web su HTTPS, console degli sviluppatori aperta</td><td>Nessun blocco CSP per <code>wss://</code> (<code>connect-src &#39;self&#39;</code>); se compare, annotare la versione: serve <code>wss://&lt;host&gt;</code> esplicito</td></tr><tr><td>P14</td><td><strong>Note in Source e in Live Preview</strong></td><td>Il cursore è sulla riga giusta in entrambe le modalità; in Live la colonna è approssimata dentro un blocco, senza salti sulla riga</td></tr><tr><td>P15</td><td><strong>Disegno:</strong> <code>user1</code> fa zoom e scroll diversi da <code>user2</code>, poi muove il mouse</td><td>Il cursore di <code>user1</code> sta sullo stesso punto della scena per <code>user2</code>, qualunque zoom e scroll</td></tr><tr><td>P16</td><td><strong>Canvas:</strong> come P15, con pan e zoom diversi</td><td>Idem, in coordinate del piano</td></tr><tr><td>P17</td><td>Lettura, basi, PDF, immagini, applicazioni</td><td>Solo avatar, nessun cursore</td></tr><tr><td>P18</td><td><strong>Oltre 4 utenti</strong> nello stesso file (aggiungere <code>admin</code> e altri account di prova)</td><td>Quattro avatar più un badge <code>+N</code> col numero degli altri; il tooltip del badge elenca i nomi</td></tr><tr><td>P19</td><td><strong>Colore coerente:</strong> lo stesso utente in file diversi, su desktop e web, con tema chiaro e scuro</td><td>Stesso colore per avatar, puntatore ed etichetta, ovunque; testo leggibile</td></tr><tr><td>P20</td><td><strong>Riduzione del movimento</strong> attiva nel sistema operativo</td><td>Il puntatore salta alla nuova posizione senza scivolare</td></tr><tr><td>P21</td><td>Sincronizzazione e modifiche durante la presenza: <code>user2</code> modifica la nota mentre <code>user1</code> la guarda</td><td>La presenza non altera il merge né la sincronizzazione: stesso comportamento di prima della 1.8.2</td></tr><tr><td>P23</td><td><strong>Spostamento fuori dallo scope:</strong> con la share di cartella di P6, <code>user1</code> sposta il file aperto da entrambi fuori da <code>Progetti/</code></td><td>Entro circa 5 s <code>user2</code> esce dalla stanza di quel file (avatar e cursori spariscono), la connessione resta aperta</td></tr><tr><td>P24</td><td><strong>Rientro dopo una revoca:</strong> dopo P8 o P23 ripristinare l&#39;accesso e riaprire il file</td><td><code>user2</code> rientra nella stanza e i due si rivedono, senza riavviare l&#39;app</td></tr><tr><td>P22</td><td><strong>Offline:</strong> togliere la rete a <code>user2</code> e rimetterla</td><td>Gli avatar spariscono da <code>user1</code> entro il TTL; al ritorno online <code>user2</code> rientra da solo nella stanza</td></tr></tbody></table><h2 id="cosa-registrare" tabindex="-1">Cosa registrare <a class="header-anchor" href="#cosa-registrare" aria-label="Permalink to &quot;Cosa registrare&quot;">​</a></h2><p>Versione (1.8.2), sistema operativo, browser, tipo di proxy, esito di P1…P24 e ogni anomalia con il file e i due utenti coinvolti. Se P12 fallisce, allegare le annotazioni dell&#39;Ingress.</p>',8)])])}const g=o(d,[["render",s]]);export{m as __pageData,g as default};
